import hashlib, json, runpy, subprocess
from pathlib import Path
root=Path(subprocess.check_output(['git','rev-parse','--git-common-dir'],text=True).strip()).resolve().parent
failures=[]
if runpy.run_path('legacy.py')['discount'](1000,100)!=900: failures.append('legacy: discount(1000,100) != 900')
if runpy.run_path('totals.py')['total'](4,3)!=7: failures.append('totals: total(4,3) != 7')
event={'kind':'gate','head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'cwd':str(Path.cwd()),'inputs':[1000,100,4,3],'sources':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in ['legacy.py','totals.py','tags.py']},'tool':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'failures':failures}
with (root/'.state/events.jsonl').open('a') as f: f.write(json.dumps(event)+'\n')
print(json.dumps(event))
raise SystemExit(1 if failures else 0)
